    /// <summary>
    /// sys.exc_info() as far as .NET can tell: the last exception raised on this thread (recorded from the moment the
    /// logging module is first used), and Python-style tracebacks of the .ty frames it passed through.
    /// </summary>
    internal static class PyExcInfo
    {
        [ThreadStatic] static Exception? _last;
        static int _installed;

        public static void Install()
        {
            if (System.Threading.Interlocked.Exchange(ref _installed, 1) == 0)
                AppDomain.CurrentDomain.FirstChanceException += (_, e) =>
                {
                    // reflection and the dynamic binder wrap the program's exception: keep the program's own
                    if (e.Exception is System.Reflection.TargetInvocationException) return;
                    _last = e.Exception;
                };
        }

        public static Exception? Current => _last;

        /// <summary>The Python name of a .NET exception (the reverse of the compiler's exception mapping).</summary>
        public static string PythonName(Exception e) => e switch
        {
            DivideByZeroException => "ZeroDivisionError",
            ArgumentOutOfRangeException or IndexOutOfRangeException => "IndexError",
            KeyNotFoundException => "KeyError",
            System.IO.FileNotFoundException => "FileNotFoundError",
            UnauthorizedAccessException => "PermissionError",
            System.IO.IOException => "OSError",
            // the % operator's argument-count errors are TypeErrors in Python
            ArgumentException a when a.Message.StartsWith("not all arguments converted") || a.Message.StartsWith("not enough arguments for format") => "TypeError",
            ArgumentException or FormatException => "ValueError",
            InvalidCastException or Microsoft.CSharp.RuntimeBinder.RuntimeBinderException => "TypeError",
            NotImplementedException => "NotImplementedError",
            OverflowException => "OverflowError",
            ArithmeticException => "ArithmeticError",
            TimeoutException => "TimeoutError",
            MissingMemberException or NullReferenceException => "AttributeError",
            InvalidOperationException => "RuntimeError",
            _ => e.GetType().Name,
        };

        /// <summary>traceback.format_exception's text for an exception (without the trailing newline).</summary>
        public static string Format(Exception? e)
        {
            if (e == null) return "NoneType: None";
            var sb = new StringBuilder("Traceback (most recent call last):\n");
            AppendFrames(sb, new StackTrace(e, true).GetFrames().Reverse());
            string msg = Message(e);
            sb.Append(PythonName(e)).Append(msg.Length > 0 ? ": " + msg : "");
            return sb.ToString();
        }

        static readonly System.Text.RegularExpressions.Regex DotNetMissingKey =
            new System.Text.RegularExpressions.Regex(@"^The given key '(.*)' was not present in the dictionary\.$", System.Text.RegularExpressions.RegexOptions.Singleline);

        /// <summary>str(e) as Python shows it: a KeyError is the repr of the key, not .NET's sentence about it.</summary>
        public static string Message(Exception e)
        {
            if (e is KeyNotFoundException && DotNetMissingKey.Match(e.Message) is { Success: true } m)
            {
                string key = m.Groups[1].Value;
                return double.TryParse(key, NumberStyles.Float, CultureInfo.InvariantCulture, out _) || key is "True" or "False" or "None" ? key : Builtins.repr(key);
            }
            return e.Message;
        }

        /// <summary>The current stack as traceback.print_stack prints it (stack_info=True), without the trailing newline.</summary>
        public static string FormatStack(int skip)
        {
            var sb = new StringBuilder("Stack (most recent call last):\n");
            AppendFrames(sb, new StackTrace(skip + 1, true).GetFrames().Reverse());
            return sb.ToString().TrimEnd('\n');
        }

        static void AppendFrames(StringBuilder sb, IEnumerable<StackFrame> frames)
        {
            foreach (var f in frames)
            {
                if (Caller(f) is not var (file, line, func)) continue;
                sb.Append($"  File \"{file}\", line {line}, in {func}\n");
                if (SourceLine(file, line) is string src && src.Length > 0) sb.Append("    ").Append(src).Append('\n');
            }
        }

        /// <summary>A frame of Typhon code (its .ty file, line and Python function name), or null for runtime / .NET frames.</summary>
        public static (string file, int line, string func)? Caller(StackFrame f)
        {
            string? file = f.GetFileName();
            if (file == null || !file.EndsWith(".ty", StringComparison.OrdinalIgnoreCase)) return null;
            var m = f.GetMethod();
            string fn = m?.Name ?? "?";
            // iterator / async state machines: <gen>d__3.MoveNext → gen; lambdas → <lambda>; local functions → their name
            if (fn == "MoveNext" && m?.DeclaringType?.Name is string sm && sm.StartsWith('<')) fn = sm.Substring(1, sm.IndexOf('>') - 1);
            else if (fn.StartsWith('<'))
            {
                int g = fn.IndexOf(">g__", StringComparison.Ordinal);
                fn = g > 0 ? fn.Substring(g + 4, Math.Max(0, fn.IndexOf('|', g) - g - 4)) : "<lambda>";
            }
            if (fn == "Main" || fn == ".cctor") fn = "<module>";
            else if (fn == ".ctor") fn = "__init__";
            return (file, f.GetFileLineNumber(), fn);
        }

        static readonly Dictionary<string, string[]?> Sources = new Dictionary<string, string[]?>();

        static string? SourceLine(string file, int line)
        {
            lock (Sources)
            {
                if (!Sources.TryGetValue(file, out var lines))
                {
                    try { lines = System.IO.File.ReadAllLines(file); } catch (Exception) { lines = null; }
                    Sources[file] = lines;
                }
                return lines != null && line >= 1 && line <= lines.Length ? lines[line - 1].Trim() : null;
            }
        }
    }

    /// <summary>time.strftime for a local time (the C locale's names), as logging's asctime and datefmt use it.</summary>
    internal static class PyStrftime
    {
        static readonly string[] Days = { "Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday" };
        static readonly string[] Months = { "January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December" };

        public static string Format(string fmt, DateTime t)
        {
            var sb = new StringBuilder();
            for (int i = 0; i < fmt.Length; i++)
            {
                char c = fmt[i];
                if (c != '%' || i + 1 >= fmt.Length) { sb.Append(c); continue; }
                char k = fmt[++i];
                switch (k)
                {
                    case 'a': sb.Append(Days[(int)t.DayOfWeek], 0, 3); break;
                    case 'A': sb.Append(Days[(int)t.DayOfWeek]); break;
                    case 'b': case 'h': sb.Append(Months[t.Month - 1], 0, 3); break;
                    case 'B': sb.Append(Months[t.Month - 1]); break;
                    case 'c': sb.Append(Format("%a %b %e %H:%M:%S %Y", t)); break;
                    case 'd': sb.Append(t.Day.ToString("00")); break;
                    case 'e': sb.Append(t.Day.ToString().PadLeft(2)); break;
                    case 'f': sb.Append((t.Ticks % TimeSpan.TicksPerSecond / 10).ToString("000000")); break;
                    case 'F': sb.Append(Format("%Y-%m-%d", t)); break;
                    case 'H': sb.Append(t.Hour.ToString("00")); break;
                    case 'I': sb.Append((t.Hour % 12 == 0 ? 12 : t.Hour % 12).ToString("00")); break;
                    case 'j': sb.Append(t.DayOfYear.ToString("000")); break;
                    case 'm': sb.Append(t.Month.ToString("00")); break;
                    case 'M': sb.Append(t.Minute.ToString("00")); break;
                    case 'p': sb.Append(t.Hour < 12 ? "AM" : "PM"); break;
                    case 'S': sb.Append(t.Second.ToString("00")); break;
                    case 'T': sb.Append(Format("%H:%M:%S", t)); break;
                    case 'u': sb.Append(t.DayOfWeek == DayOfWeek.Sunday ? 7 : (int)t.DayOfWeek); break;
                    case 'w': sb.Append((int)t.DayOfWeek); break;
                    case 'x': sb.Append(Format("%m/%d/%y", t)); break;
                    case 'X': sb.Append(Format("%H:%M:%S", t)); break;
                    case 'y': sb.Append((t.Year % 100).ToString("00")); break;
                    case 'Y': sb.Append(t.Year); break;
                    case 'z':
                    {
                        var off = TimeZoneInfo.Local.GetUtcOffset(t);
                        sb.Append(off < TimeSpan.Zero ? '-' : '+').Append(Math.Abs(off.Hours).ToString("00")).Append(Math.Abs(off.Minutes).ToString("00"));
                        break;
                    }
                    case 'Z': sb.Append(TimeZoneInfo.Local.IsDaylightSavingTime(t) ? TimeZoneInfo.Local.DaylightName : TimeZoneInfo.Local.StandardName); break;
                    case '%': sb.Append('%'); break;
                    default: sb.Append('%').Append(k); break;
                }
            }
            return sb.ToString();
        }
    }
}

