        internal static long CheckLevel(object? level)
        {
            switch (level)
            {
                case long l: return l;
                case int i: return i;
                case bool b: return b ? 1 : 0;
                case string s:
                    lock (_lock) { if (_nameToLevel.TryGetValue(s, out var v)) return v; }
                    throw new ArgumentException("Unknown level: " + Builtins.repr(s));
