                this.exc_info = exc_info;
                stack_info = sinfo;
                this.lineno = lineno;
                funcName = func;
                long unixTicks = ticks - DateTime.UnixEpoch.Ticks;
                created = unixTicks / (double)TimeSpan.TicksPerSecond;
                msecs = unixTicks % TimeSpan.TicksPerSecond / TimeSpan.TicksPerMillisecond + 0.0;
                relativeCreated = (ticks - _startTicks) / (double)TimeSpan.TicksPerMillisecond;
                if (logThreads)
