        /// <summary>Formats a record as text: the %(name)s / {name} / $name fields of a format string, the time, the exception.</summary>
        internal class Formatter : IPyRepr
        {
            public readonly string _fmt;
            public string? datefmt;
            internal readonly char _style;
            readonly IDictionary? _defaults;
            public string default_time_format = "%Y-%m-%d %H:%M:%S";
            public string? default_msec_format = "%s,%03d";
            static readonly Regex PercentValidation = new Regex(@"%\(\w+\)[#0+ -]*(\*|\d+)?(\.(\*|\d+))?[diouxefgcrsa%]", RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
            static readonly string[] CallerFields = { "pathname", "filename", "module", "lineno", "funcName" };
            static readonly Regex PercentKeys = new Regex(@"%\(([^)]*)\)", RegexOptions.CultureInvariant);

            public Formatter(string? fmt = null, string? datefmt = null, string style = "%", bool validate = true, KwOnly _ = default, IDictionary? defaults = null)
            {
                if (style != "%" && style != "{" && style != "$") throw new ArgumentException("Style must be one of: %,{,$");
                _style = style[0];
                _fmt = !string.IsNullOrEmpty(fmt) ? fmt : _style == '%' ? "%(message)s" : _style == '{' ? "{message}" : "${message}";
                _defaults = defaults;
                if (validate) Validate();
                this.datefmt = datefmt;
                if (CallerFields.Any(f => _fmt.Contains(f))) _wantCaller = true;
            }

            void Validate()
            {
                if (_style == '%' && !PercentValidation.IsMatch(_fmt)) throw new ArgumentException($"Invalid format '{_fmt}' for '%' style");
                if (_style == '{' && !Regex.IsMatch(_fmt, @"\{[^{}]+\}")) throw new ArgumentException("invalid format: no fields");
                if (_style == '$' && !Regex.IsMatch(_fmt, @"\$(\w+|\{\w+\})")) throw new ArgumentException("invalid format: no fields");
            }

            public bool usesTime() => _style switch
            {
                '%' => _fmt.Contains("%(asctime)"),
                '{' => _fmt.Contains("{asctime"),
                _ => _fmt.Contains("$asctime") || _fmt.Contains("${asctime}"),
            };

            public virtual string formatTime(LogRecord record, string? datefmt = null)
            {
                var ct = DateTime.UnixEpoch.AddTicks((long)Math.Round(record.created * TimeSpan.TicksPerSecond)).ToLocalTime();
                if (!string.IsNullOrEmpty(datefmt)) return PyStrftime.Format(datefmt, ct);
                string s = PyStrftime.Format(default_time_format, ct);
                if (default_msec_format != null) s = Builtins.__percent_args(default_msec_format, new object?[] { s, record.msecs });
                return s;
            }

            public virtual string formatException(object? exc_info) => PyExcInfo.Format(exc_info as Exception);

            public virtual string formatStack(string stack_info) => stack_info;

            public virtual string formatMessage(LogRecord record)
            {
                var values = record.__dict__;
                if (_defaults != null)
                    foreach (DictionaryEntry kv in _defaults)
                        if (!values.ContainsKey((string)kv.Key)) values[(string)kv.Key] = kv.Value;
                try
                {
                    if (_style == '%')
                        foreach (Match m in PercentKeys.Matches(_fmt))
                            if (!values.ContainsKey(m.Groups[1].Value)) throw new KeyNotFoundException(Builtins.repr(m.Groups[1].Value));
                    return _style switch
                    {
                        '%' => Builtins.__percent(_fmt, values),
                        '{' => BraceFormat(_fmt, values),
                        _ => TemplateFormat(_fmt, values),
                    };
                }
                catch (KeyNotFoundException e) { throw new ArgumentException("Formatting field not found in record: " + e.Message); }
            }

            public virtual string format(LogRecord record)
            {
                record.message = record.getMessage();
                if (usesTime()) record.asctime = formatTime(record, datefmt);
                string s = formatMessage(record);
                if (record.Exception != null || record.exc_info != null && !(record.exc_info is bool b && !b))
                    record.exc_text ??= formatException(record.Exception);
                if (!string.IsNullOrEmpty(record.exc_text))
                {
                    if (!s.EndsWith("\n")) s += "\n";
                    s += record.exc_text;
                }
                if (!string.IsNullOrEmpty(record.stack_info))
                {
                    if (!s.EndsWith("\n")) s += "\n";
                    s += formatStack(record.stack_info);
                }
                return s;
            }

            public string __repr__() => $"<logging.Formatter object at 0x{RuntimeHelpers.GetHashCode(this):x12}>";
            public override string ToString() => __repr__();

            /// <summary>str.format(**values) for the {name}, {name:spec} and {name!r} fields of a { style format.</summary>
            static string BraceFormat(string fmt, IDictionary<string, object?> values)
            {
                var sb = new StringBuilder();
                for (int i = 0; i < fmt.Length; i++)
                {
                    char c = fmt[i];
                    if (c == '{' && i + 1 < fmt.Length && fmt[i + 1] == '{') { sb.Append('{'); i++; continue; }
                    if (c == '}' && i + 1 < fmt.Length && fmt[i + 1] == '}') { sb.Append('}'); i++; continue; }
                    if (c != '{') { sb.Append(c); continue; }
                    int end = fmt.IndexOf('}', i);
                    if (end < 0) throw new ArgumentException("Single '{' encountered in format string");
                    string field = fmt.Substring(i + 1, end - i - 1), spec = "";
                    int colon = field.IndexOf(':');
                    if (colon >= 0) { spec = field.Substring(colon + 1); field = field.Substring(0, colon); }
                    char conv = '\0';
                    int bang = field.IndexOf('!');
                    if (bang >= 0) { conv = field[bang + 1]; field = field.Substring(0, bang); }
                    if (!values.TryGetValue(field, out var v)) throw new KeyNotFoundException(Builtins.repr(field));
                    object? shown = conv == 'r' ? Builtins.repr(v) : conv == 's' ? Builtins.str(v) : conv == 'a' ? Builtins.ascii(v) : v;
                    sb.Append(Builtins.format(shown, spec));
                    i = end;
                }
                return sb.ToString();
            }

            /// <summary>string.Template(fmt).substitute(values) for a $ style format.</summary>
            static string TemplateFormat(string fmt, IDictionary<string, object?> values) =>
                Regex.Replace(fmt, @"\$(?:(\$)|([_a-zA-Z][_a-zA-Z0-9]*)|\{([_a-zA-Z][_a-zA-Z0-9]*)\})", m =>
