        /// <summary>Lets through the records of a logger and its descendants (Filter("a.b") passes "a.b" and "a.b.c").</summary>
        internal class Filter
        {
            public readonly string name;
            readonly int nlen;
            public Filter(string name = "") { this.name = name; nlen = name.Length; }
            public virtual object? filter(LogRecord record)
            {
                if (nlen == 0) return true;
                string rn = record.name ?? "";
                if (name == rn) return true;
                if (!rn.StartsWith(name, StringComparison.Ordinal)) return false;
                return rn.Length > nlen && rn[nlen] == '.';
            }
        }

        /// <summary>What loggers and handlers share: a list of filters (Filter objects or functions of a record).</summary>
        internal class Filterer
        {
            public readonly List<object> filters = new List<object>();

            public void addFilter(Filter filter) { if (!filters.Contains(filter)) filters.Add(filter); }
            public void addFilter(Func<LogRecord, object?> filter) { if (!filters.Contains(filter)) filters.Add(filter); }
            public void addFilter(object filter) { if (!filters.Contains(filter)) filters.Add(filter); }
            public void removeFilter(object filter) => filters.Remove(filter);

            /// <summary>Applies the filters: false if one rejects the record, else the record (a filter may return a replacement).</summary>
            public object filter(LogRecord record)
            {
                foreach (var f in filters.ToList())
                {
                    object? result = f switch
                    {
                        Filter flt => flt.filter(record),
                        Func<LogRecord, object?> fn => fn(record),
                        _ => ((dynamic)f).filter(record),
                    };
                    if (!Builtins.truthy(result)) return false;
                    if (result is LogRecord replacement) record = replacement;
                }
                return record;
            }
        }

        // ── handlers ──

        /// <summary>Sends records somewhere (its subclasses implement emit), if they reach its level and pass its filters.</summary>
        internal class Handler : Filterer, IPyRepr
        {
            public long level;
            public Formatter? formatter;
            string? _name;
            internal bool _closed;

            public Handler(object? level = null)
            {
                this.level = level == null ? NOTSET : CheckLevel(level);
                lock (_lock) _handlerList.Add(new WeakReference<Handler>(this));
            }

            public string? name
            {
                get => _name;
                set
                {
                    lock (_lock)
                    {
                        if (_name != null) _handlers.Remove(_name);
                        _name = value;
                        if (!string.IsNullOrEmpty(value)) _handlers[value] = this;
                    }
                }
            }

            public void setLevel(object? level) => this.level = CheckLevel(level);
            public void setFormatter(Formatter? fmt) => formatter = fmt;
            public void createLock() { }
            public void acquire() { }
            public void release() { }

            public virtual string format(LogRecord record) => (formatter ?? _defaultFormatter).format(record);

            public virtual void emit(LogRecord record) => throw new NotImplementedException("emit must be implemented by Handler subclasses");

            public virtual object handle(LogRecord record)
            {
                var rv = filter(record);
                if (rv is LogRecord r)
                {
                    lock (this) emit(r);
                    return r;
                }
                return false;
            }

            public virtual void flush() { }

            public virtual void close()
            {
                lock (_lock)
                {
                    _closed = true;
                    if (_name != null) _handlers.Remove(_name);
                }
            }

            /// <summary>An error in emit(): reported on stderr (when raiseExceptions), logging carries on.</summary>
            public virtual void handleError(LogRecord record, Exception? error = null)
            {
                if (!raiseExceptions) return;
                var err = Console.Error;
                err.Write("--- Logging error ---\n");
                err.Write(PyExcInfo.Format(error) + "\n");
                err.Write("Call stack:\n");
                string stack = PyExcInfo.FormatStack(1);
                int nl = stack.IndexOf('\n');
                if (nl >= 0) err.Write(stack.Substring(nl + 1) + "\n");
                string argsText = record.args is object?[] a ? Builtins.repr(new PyTuple<object?>(a)) : Builtins.str(record.args);
                err.Write($"Message: {Builtins.repr(record.msg)}\nArguments: {argsText}\n");
            }

            protected virtual string ReprDetail() => "";
            public string __repr__() => $"<{GetType().Name} {ReprDetail()}({LevelName(level)})>";
            public override string ToString() => __repr__();
        }

        /// <summary>Writes each record, formatted, to a stream (sys.stderr by default) followed by the terminator.</summary>
        internal class StreamHandler : Handler
        {
            public string terminator = "\n";
            object? _stream;

            public StreamHandler(object? stream = null) : base() { _stream = stream ?? sys_.stderr; }

            public virtual object? stream { get => _stream; set => _stream = value; }

            public override void flush() { if (stream != null) PyConsole.Flush(stream); }

            public override void emit(LogRecord record)
            {
                try
                {
                    string msg = format(record);
                    PyConsole.Write(stream, msg + terminator);
                    flush();
                }
                catch (Exception e) when (!(e is StackOverflowException))
                {
                    handleError(record, e);
                }
            }

            public object? setStream(object? stream)
            {
                if (ReferenceEquals(stream, _stream)) return null;
                var old = _stream;
                flush();
                _stream = stream;
                return old;
            }

            internal static string StreamName(object? s) => s switch
            {
                PyTextStream ts when ReferenceEquals(ts, sys_.stdout) => "<stdout>",
                PyTextStream ts when ReferenceEquals(ts, sys_.stderr) => "<stderr>",
                PyTextStream => "<stdin>",
                PyFile f => f.name,
                _ => "",
            };

            protected override string ReprDetail() { string n = StreamName(stream); return n.Length > 0 ? n + " " : ""; }
        }

        /// <summary>Appends formatted records to a file (opened at once, or at the first record with delay=True).</summary>
        internal class FileHandler : StreamHandler
        {
            public readonly string baseFilename, mode;
            public readonly string? encoding, errors;
            public readonly bool delay;

            public FileHandler(string filename, string mode = "a", string? encoding = null, bool delay = false, string? errors = null) : base((object?)sys_.stderr)
            {
                baseFilename = System.IO.Path.GetFullPath(filename);
                this.mode = mode;
                this.encoding = mode.Contains('b') ? encoding : encoding ?? "utf-8";
                this.errors = errors;
                this.delay = delay;
                stream = delay ? null : _open();
            }

            protected object _open() => new PyFile(baseFilename, mode, encoding, errors);

            public override void close()
            {
                lock (this)
                {
                    try
                    {
                        if (stream is PyFile f)
                        {
                            try { flush(); }
                            finally { stream = null; f.close(); }
                        }
                    }
                    finally { base.close(); }
                }
            }

            public override void emit(LogRecord record)
            {
                if (stream == null && (mode != "w" || !_closed)) stream = _open();
                if (stream != null) base.emit(record);
            }

            protected override string ReprDetail() => baseFilename + " ";
        }

        /// <summary>Discards records (a library's way of saying "no output unless configured").</summary>
        internal class NullHandler : Handler
        {
            public NullHandler() : base() { }
            public override object handle(LogRecord record) => false;
            public override void emit(LogRecord record) { }
        }

        /// <summary>The last-resort handler: whatever sys.stderr is, bare messages.</summary>
        internal sealed class _StderrHandler : StreamHandler
        {
            public _StderrHandler(long level = NOTSET) : base() { this.level = level; }
            public override object? stream { get => sys_.stderr; set { } }
        }

        public static Handler? getHandlerByName(string name) { lock (_lock) return _handlers.TryGetValue(name, out var h) ? h : null; }
        public static HashSet<string> getHandlerNames() { lock (_lock) return new HashSet<string>(_handlers.Keys); }

        // ── loggers ──

        sealed class PlaceHolder
        {
            public readonly List<Logger> loggerMap = new List<Logger>();
            public PlaceHolder(Logger l) { loggerMap.Add(l); }
            public void append(Logger l) { if (!loggerMap.Contains(l)) loggerMap.Add(l); }
        }

        /// <summary>A named channel: its level, handlers and filters; records propagate to the handlers of its ancestors.</summary>
        internal class Logger : Filterer, IPyRepr
        {
            public string name;
            public long level;
            public Logger? parent;
            public bool propagate = true;
            public readonly List<Handler> handlers = new List<Handler>();
            public bool disabled;
            internal readonly Dictionary<long, bool> _cache = new Dictionary<long, bool>();

            public Logger(string name, object? level = null) { this.name = name; this.level = level == null ? NOTSET : CheckLevel(level); }

            public Logger root => logging.root;

            public void setLevel(object? level) { this.level = CheckLevel(level); ClearCaches(); }

            public long getEffectiveLevel()
            {
                for (var l = this; l != null; l = l.parent) if (l.level != 0) return l.level;
                return NOTSET;
            }

            public bool isEnabledFor(long level)
            {
                if (disabled) return false;
                lock (_lock)
                {
                    if (_cache.TryGetValue(level, out var on)) return on;
                    return _cache[level] = _disable < level && level >= getEffectiveLevel();
                }
            }

            public Logger getChild(string suffix) => getLogger(ReferenceEquals(this, logging.root) ? suffix : name + "." + suffix);

            public HashSet<Logger> getChildren()
            {
                static int HierLevel(Logger l) => ReferenceEquals(l, logging.root) ? 0 : 1 + l.name.Count(c => c == '.');
                lock (_lock)
                    return new HashSet<Logger>(_loggerDict.Values.OfType<Logger>().Where(l => ReferenceEquals(l.parent, this) && HierLevel(l) == 1 + HierLevel(this)));
            }

            public void addHandler(Handler hdlr) { lock (_lock) if (!handlers.Contains(hdlr)) handlers.Add(hdlr); }
            public void removeHandler(Handler hdlr) { lock (_lock) handlers.Remove(hdlr); }

            public bool hasHandlers()
            {
                for (var c = this; c != null; c = c.parent)
                {
                    if (c.handlers.Count > 0) return true;
                    if (!c.propagate) break;
                }
                return false;
            }

            // debug / info / warning / error / critical (and fatal, warn, exception, log): the message, its % arguments, and
            // the keywords exc_info, stack_info, stacklevel and extra (with up to two message arguments)
            public void debug(object? msg, params object?[] args) => Log(DEBUG, msg, args);
            public void debug(object? msg, KwOnly _ = default, object? exc_info = null, bool stack_info = false, long stacklevel = 1, IDictionary? extra = null) => Log(DEBUG, msg, Array.Empty<object?>(), exc_info, stack_info, stacklevel, extra);
            public void debug(object? msg, object? a1, KwOnly _ = default, object? exc_info = null, bool stack_info = false, long stacklevel = 1, IDictionary? extra = null) => Log(DEBUG, msg, new[] { a1 }, exc_info, stack_info, stacklevel, extra);
            public void debug(object? msg, object? a1, object? a2, KwOnly _ = default, object? exc_info = null, bool stack_info = false, long stacklevel = 1, IDictionary? extra = null) => Log(DEBUG, msg, new[] { a1, a2 }, exc_info, stack_info, stacklevel, extra);

            public void info(object? msg, params object?[] args) => Log(INFO, msg, args);
            public void info(object? msg, KwOnly _ = default, object? exc_info = null, bool stack_info = false, long stacklevel = 1, IDictionary? extra = null) => Log(INFO, msg, Array.Empty<object?>(), exc_info, stack_info, stacklevel, extra);
            public void info(object? msg, object? a1, KwOnly _ = default, object? exc_info = null, bool stack_info = false, long stacklevel = 1, IDictionary? extra = null) => Log(INFO, msg, new[] { a1 }, exc_info, stack_info, stacklevel, extra);
            public void info(object? msg, object? a1, object? a2, KwOnly _ = default, object? exc_info = null, bool stack_info = false, long stacklevel = 1, IDictionary? extra = null) => Log(INFO, msg, new[] { a1, a2 }, exc_info, stack_info, stacklevel, extra);

            public void warning(object? msg, params object?[] args) => Log(WARNING, msg, args);
            public void warning(object? msg, KwOnly _ = default, object? exc_info = null, bool stack_info = false, long stacklevel = 1, IDictionary? extra = null) => Log(WARNING, msg, Array.Empty<object?>(), exc_info, stack_info, stacklevel, extra);
            public void warning(object? msg, object? a1, KwOnly _ = default, object? exc_info = null, bool stack_info = false, long stacklevel = 1, IDictionary? extra = null) => Log(WARNING, msg, new[] { a1 }, exc_info, stack_info, stacklevel, extra);
            public void warning(object? msg, object? a1, object? a2, KwOnly _ = default, object? exc_info = null, bool stack_info = false, long stacklevel = 1, IDictionary? extra = null) => Log(WARNING, msg, new[] { a1, a2 }, exc_info, stack_info, stacklevel, extra);
            public void warn(object? msg, params object?[] args) => Log(WARNING, msg, args);

            public void error(object? msg, params object?[] args) => Log(ERROR, msg, args);
            public void error(object? msg, KwOnly _ = default, object? exc_info = null, bool stack_info = false, long stacklevel = 1, IDictionary? extra = null) => Log(ERROR, msg, Array.Empty<object?>(), exc_info, stack_info, stacklevel, extra);
            public void error(object? msg, object? a1, KwOnly _ = default, object? exc_info = null, bool stack_info = false, long stacklevel = 1, IDictionary? extra = null) => Log(ERROR, msg, new[] { a1 }, exc_info, stack_info, stacklevel, extra);
            public void error(object? msg, object? a1, object? a2, KwOnly _ = default, object? exc_info = null, bool stack_info = false, long stacklevel = 1, IDictionary? extra = null) => Log(ERROR, msg, new[] { a1, a2 }, exc_info, stack_info, stacklevel, extra);

            public void exception(object? msg, params object?[] args) => Log(ERROR, msg, args, true);
            public void exception(object? msg, KwOnly _ = default, object? exc_info = null, bool stack_info = false, long stacklevel = 1, IDictionary? extra = null) => Log(ERROR, msg, Array.Empty<object?>(), exc_info ?? true, stack_info, stacklevel, extra);
            public void exception(object? msg, object? a1, KwOnly _ = default, object? exc_info = null, bool stack_info = false, long stacklevel = 1, IDictionary? extra = null) => Log(ERROR, msg, new[] { a1 }, exc_info ?? true, stack_info, stacklevel, extra);
            public void exception(object? msg, object? a1, object? a2, KwOnly _ = default, object? exc_info = null, bool stack_info = false, long stacklevel = 1, IDictionary? extra = null) => Log(ERROR, msg, new[] { a1, a2 }, exc_info ?? true, stack_info, stacklevel, extra);

            public void critical(object? msg, params object?[] args) => Log(CRITICAL, msg, args);
            public void critical(object? msg, KwOnly _ = default, object? exc_info = null, bool stack_info = false, long stacklevel = 1, IDictionary? extra = null) => Log(CRITICAL, msg, Array.Empty<object?>(), exc_info, stack_info, stacklevel, extra);
            public void critical(object? msg, object? a1, KwOnly _ = default, object? exc_info = null, bool stack_info = false, long stacklevel = 1, IDictionary? extra = null) => Log(CRITICAL, msg, new[] { a1 }, exc_info, stack_info, stacklevel, extra);
            public void critical(object? msg, object? a1, object? a2, KwOnly _ = default, object? exc_info = null, bool stack_info = false, long stacklevel = 1, IDictionary? extra = null) => Log(CRITICAL, msg, new[] { a1, a2 }, exc_info, stack_info, stacklevel, extra);
            public void fatal(object? msg, params object?[] args) => Log(CRITICAL, msg, args);

            public void log(long level, object? msg, params object?[] args) => Log(level, msg, args);
            public void log(long level, object? msg, KwOnly _ = default, object? exc_info = null, bool stack_info = false, long stacklevel = 1, IDictionary? extra = null) => Log(level, msg, Array.Empty<object?>(), exc_info, stack_info, stacklevel, extra);
            public void log(long level, object? msg, object? a1, KwOnly _ = default, object? exc_info = null, bool stack_info = false, long stacklevel = 1, IDictionary? extra = null) => Log(level, msg, new[] { a1 }, exc_info, stack_info, stacklevel, extra);
            public void log(long level, object? msg, object? a1, object? a2, KwOnly _ = default, object? exc_info = null, bool stack_info = false, long stacklevel = 1, IDictionary? extra = null) => Log(level, msg, new[] { a1, a2 }, exc_info, stack_info, stacklevel, extra);

            internal void Log(long level, object? msg, object?[] args, object? exc_info = null, bool stack_info = false, long stacklevel = 1, IDictionary? extra = null)
            {
                if (!isEnabledFor(level)) return;
                for (int i = 0; i < args.Length; i++) args[i] = argparse.Norm(args[i]);
                string fn = "(unknown file)", func = "(unknown function)";
                long lno = 0;
                string? sinfo = null;
                if (_wantCaller || stack_info)
                {
                    long skip = Math.Max(1, stacklevel);
                    foreach (var f in new StackTrace(1, true).GetFrames())
                    {
                        if (PyExcInfo.Caller(f) is not var (file, line, name)) continue;
                        if (--skip > 0) continue;
                        fn = file; lno = line; func = name;
                        break;
                    }
                    if (stack_info) sinfo = PyExcInfo.FormatStack(1);
                }
                Exception? exc = exc_info switch
                {
                    null => null,
                    bool b => b ? PyExcInfo.Current : null,
                    Exception e => e,
                    ITuple t when t.Length == 3 => t[1] as Exception,
                    _ => Builtins.truthy(exc_info) ? PyExcInfo.Current : null,
                };
                var record = makeRecord(name, level, fn, lno, msg, args, exc_info is bool eb && !eb ? null : exc_info, func, extra, sinfo);
                record.Exception = exc;
                handle(record);
            }

            public LogRecord makeRecord(string name, long level, string fn, long lno, object? msg, object? args, object? exc_info, string? func = null, IDictionary? extra = null, string? sinfo = null)
            {
                var rv = new LogRecord(name, level, fn, lno, msg, args, exc_info, func, sinfo);
                if (extra != null)
                    foreach (DictionaryEntry kv in extra)
                    {
                        string key = (string)kv.Key;
                        if (key == "message" || key == "asctime" || rv.__dict__.ContainsKey(key)) throw new KeyNotFoundException($"\"Attempt to overwrite {Builtins.repr(key)} in LogRecord\"");
                        rv.extra[key] = kv.Value;
                    }
                return rv;
            }

            public void handle(LogRecord record)
            {
                if (disabled) return;
                var rv = filter(record);
                if (rv is LogRecord r) callHandlers(r);
            }

            public void callHandlers(LogRecord record)
            {
                int found = 0;
                for (var c = this; c != null; c = c.propagate ? c.parent : null)
                    foreach (var h in c.handlers.ToList())
                    {
                        found++;
                        if (record.levelno >= h.level) h.handle(record);
                    }
                if (found == 0 && lastResort != null && record.levelno >= lastResort.level) lastResort.handle(record);
            }

            public string __repr__() => $"<{(ReferenceEquals(this, logging.root) ? "RootLogger" : GetType().Name)} {name} ({LevelName(getEffectiveLevel())})>";
            public override string ToString() => __repr__();
        }

        internal sealed class RootLogger : Logger
        {
            public RootLogger(long level) : base("root", level) { }
        }

        /// <summary>getLogger(name): the logger of that name (created with its place in the hierarchy), or the root logger.</summary>
        public static Logger getLogger(string? name = null)
        {
            if (string.IsNullOrEmpty(name) || name == root.name) return root;
            lock (_lock)
            {
                Logger rv;
                if (_loggerDict.TryGetValue(name, out var existing))
                {
                    if (existing is Logger l) return l;
                    var ph = (PlaceHolder)existing;
                    rv = new Logger(name);
                    _loggerDict[name] = rv;
                    FixupChildren(ph, rv);
                    FixupParents(rv);
                }
                else
                {
                    rv = new Logger(name);
                    _loggerDict[name] = rv;
                    FixupParents(rv);
                }
                return rv;
            }
        }

        static void FixupParents(Logger alogger)
        {
            string name = alogger.name;
            int i = name.LastIndexOf('.');
            Logger? rv = null;
            while (i > 0 && rv == null)
            {
                string substr = name.Substring(0, i);
                if (!_loggerDict.TryGetValue(substr, out var obj)) _loggerDict[substr] = new PlaceHolder(alogger);
                else if (obj is Logger l) rv = l;
                else ((PlaceHolder)obj).append(alogger);
                i = i - 1 > 0 ? name.LastIndexOf('.', i - 1) : -1;
            }
            alogger.parent = rv ?? root;
        }

        static void FixupChildren(PlaceHolder ph, Logger alogger)
        {
            string name = alogger.name;
            foreach (var c in ph.loggerMap)
                if (c.parent == null || !c.parent.name.StartsWith(name, StringComparison.Ordinal) || c.parent.name.Length < name.Length)
                {
                    alogger.parent = c.parent;
                    c.parent = alogger;
                }
        }

        public static Type getLoggerClass() => typeof(Logger);

        // ── configuration ──

        /// <summary>basicConfig(...): a handler with a formatter for the root logger, unless it has handlers already (or force=True).</summary>
        public static void basicConfig(string? filename = null, string? filemode = null, string? format = null, string? datefmt = null, string? style = null,
                                       object? level = null, object? stream = null, IEnumerable? handlers = null, bool force = false,
                                       string? encoding = null, string? errors = "backslashreplace")
        {
            lock (_lock)
            {
                if (force)
                    foreach (var h in root.handlers.ToList()) { root.removeHandler(h); h.close(); }
                if (root.handlers.Count > 0) return;
                List<Handler> hs;
                if (handlers == null)
                {
                    if (stream != null && filename != null) throw new ArgumentException("'stream' and 'filename' should not be specified together");
                    if (!string.IsNullOrEmpty(filename))
                    {
                        string mode = filemode ?? "a";
                        hs = new List<Handler> { new FileHandler(filename, mode, mode.Contains('b') ? encoding : encoding ?? "utf-8", errors: mode.Contains('b') ? null : errors) };
                    }
                    else hs = new List<Handler> { new StreamHandler(stream) };
                }
                else
                {
                    if (stream != null || filename != null) throw new ArgumentException("'stream' or 'filename' should not be specified together with 'handlers'");
                    hs = handlers.Cast<Handler>().ToList();
                }
                string st = style ?? "%";
                if (st != "%" && st != "{" && st != "$") throw new ArgumentException("Style must be one of: %,{,$");
                var fmt = new Formatter(format ?? (st == "%" ? BASIC_FORMAT : st == "{" ? "{levelname}:{name}:{message}" : "${levelname}:${name}:${message}"), datefmt, st);
                foreach (var h in hs)
                {
                    if (h.formatter == null) h.setFormatter(fmt);
                    root.addHandler(h);
                }
                if (level != null) root.setLevel(level);
            }
        }

        /// <summary>shutdown(): flushes and closes every handler (at exit, like CPython's atexit hook).</summary>
        public static void shutdown()
        {
            List<WeakReference<Handler>> list;
            lock (_lock) list = _handlerList.ToList();
            list.Reverse();
            foreach (var wr in list)
            {
                if (!wr.TryGetTarget(out var h)) continue;
                try { h.flush(); h.close(); }
                catch (Exception) { if (raiseExceptions) throw; }
            }
        }

        public static void captureWarnings(bool capture) { }

        // ── module-level functions: the root logger, configured by basicConfig() on first use ──

        static Logger Root() { if (root.handlers.Count == 0) basicConfig(); return root; }

