        public static void debug(object? msg, KwOnly _ = default, object? exc_info = null, bool stack_info = false, long stacklevel = 1, IDictionary? extra = null) => Root().Log(DEBUG, msg, Array.Empty<object?>(), exc_info, stack_info, stacklevel, extra);
        public static void debug(object? msg, object? a1, KwOnly _ = default, object? exc_info = null, bool stack_info = false, long stacklevel = 1, IDictionary? extra = null) => Root().Log(DEBUG, msg, new[] { a1 }, exc_info, stack_info, stacklevel, extra);
        public static void debug(object? msg, object? a1, object? a2, KwOnly _ = default, object? exc_info = null, bool stack_info = false, long stacklevel = 1, IDictionary? extra = null) => Root().Log(DEBUG, msg, new[] { a1, a2 }, exc_info, stack_info, stacklevel, extra);

        public static void info(object? msg, params object?[] args) => Root().Log(INFO, msg, args);
        public static void info(object? msg, KwOnly _ = default, object? exc_info = null, bool stack_info = false, long stacklevel = 1, IDictionary? extra = null) => Root().Log(INFO, msg, Array.Empty<object?>(), exc_info, stack_info, stacklevel, extra);
        public static void info(object? msg, object? a1, KwOnly _ = default, object? exc_info = null, bool stack_info = false, long stacklevel = 1, IDictionary? extra = null) => Root().Log(INFO, msg, new[] { a1 }, exc_info, stack_info, stacklevel, extra);
        public static void info(object? msg, object? a1, object? a2, KwOnly _ = default, object? exc_info = null, bool stack_info = false, long stacklevel = 1, IDictionary? extra = null) => Root().Log(INFO, msg, new[] { a1, a2 }, exc_info, stack_info, stacklevel, extra);

        public static void warning(object? msg, params object?[] args) => Root().Log(WARNING, msg, args);
